from solution import maximum_Sum


def test_issue_example_from_issue():
    """Maximum sum of elements of list in a list of lists is 33 for the example."""
    assert maximum_Sum([[1, 2, 3], [4, 5, 6], [10, 11, 12], [7, 8, 9]]) == 33  # 10+11+12=33


def test_issue_single_inner_list():
    """Maximum sum of elements of list in a list of lists with one list is its sum."""
    assert maximum_Sum([[4, 5, 6]]) == 15  # 4+5+6=15


def test_issue_maximum_in_first_position():
    """Maximum sum of elements of list in a list of lists can be the first list."""
    assert maximum_Sum([[20, 20], [1, 2, 3], [4, 5, 6]]) == 40  # 20+20=40


def test_issue_maximum_in_last_position():
    """Maximum sum of elements of list in a list of lists can be the last list."""
    assert maximum_Sum([[1, 1, 1], [2, 2, 2], [9, 1, 0]]) == 10  # 9+1+0=10


def test_issue_all_negative_sums():
    """Maximum sum of elements of list in a list of lists with negatives is least negative."""
    assert maximum_Sum([[-1, -2], [-5, -1], [-4, -4]]) == -3  # -1+-2=-3


def test_issue_mixed_negative_and_positive():
    """Maximum sum of elements of list in a list of lists picks positive over negative."""
    assert maximum_Sum([[-5, -5], [1, 2]]) == 3  # 1+2=3


def test_issue_varying_inner_lengths():
    """Maximum sum of elements of list in a list of lists works with different lengths."""
    assert maximum_Sum([[1, 2], [100], [1, 2, 3, 4]]) == 100  # 1+2=3, 100=100, 1+2+3+4=10, max=100


def test_issue_tied_maximum():
    """Maximum sum of elements of list in a list of lists with tie returns that sum."""
    assert maximum_Sum([[1, 2], [3, 0]]) == 3  # 1+2=3, 3+0=3


def test_issue_two_element_lists():
    """Maximum sum of elements of list in a list of lists works for two-element lists."""
    assert maximum_Sum([[1, 4], [2, 8], [3, 4]]) == 10  # 2+8=10


def test_issue_empty_inner_list():
    """Maximum sum of elements of list in a list of lists handles an empty inner list."""
    assert maximum_Sum([[], [1, 2]]) == 3  # 1+2=3, sum([])=0


def test_issue_all_zeros():
    """Maximum sum of elements of list in a list of lists of zeros is zero."""
    assert maximum_Sum([[0, 0], [0, 0, 0]]) == 0  # 0+0=0
